// Filter: keep only items with 'guideline', 'recommendation', 'clinical' in title
const keywords = ['guideline', 'recommendation', 'clinical', 'technical guidance'];
const exclusions = ['news', 'press release', 'event'];

return $input.all()
  .filter(item => {
    const title = (item.json.title || '').toLowerCase();
    if (exclusions.some(e => title.includes(e))) return false;
    return keywords.some(k => title.includes(k));
  })
  .slice(0, 10);  // safety cap

const cheerio = require('cheerio');
const crypto = require('crypto');

const html = $input.first().json.data || $input.first().json.body || '';
const rssItem = $('Loop Over Items').item.json;
const config = $('Set Source Config').first().json;

const $$ = cheerio.load(html);
$$('nav, footer, aside, script, style, noscript').remove();
$$('.sidebar, .cookie-banner, .advertisement').remove();
const text = ($$('main').text() || $$('article').text() || $$('body').text())
  .replace(/\s+/g, ' ').trim();

if (text.length < 500) {
  return [];  // skip too short
}

const hash = crypto.createHash('sha256').update(html).digest('hex');

// Chunking ~800 words, overlap 100
const words = text.split(' ');
const chunks = [];
const chunkSize = 800;
const overlap = 100;
for (let i = 0; i < words.length; i += chunkSize - overlap) {
  const slice = words.slice(i, i + chunkSize).join(' ');
  if (slice.length < 100) break;
  chunks.push({ chunk_index: chunks.length, section: null, content: slice });
}

// Derive guideline_code from URL last segment
let code;
try {
  const u = new URL(rssItem.link);
  const last = u.pathname.split('/').filter(Boolean).pop() || '';
  code = last.replace(/\.(html|php|aspx?)$/i, '').slice(0, 100);
  if (code.length < 3) {
    code = (rssItem.title || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 100);
  }
} catch {
  code = (rssItem.title || 'unknown').toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 100);
}

return [{
  json: {
    source: config.source_code,
    guideline_code: code,
    title: rssItem.title,
    url: rssItem.link,
    language: config.language,
    pub_date: rssItem.pubDate || new Date().toISOString(),
    text_preview: text.slice(0, 3000),
    full_text: text,
    source_hash: hash,
    chunks: chunks
  }
}];

