// Generate embeddings for each chunk via OpenAI batch endpoint
const doc = $('Extract & Chunk').first().json;
const chunks = doc.chunks;

if (!chunks || chunks.length === 0) return [];

// Call OpenAI embeddings endpoint directly
const openaiKey = $credentials.openAi.apiKey;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.openai.com/v1/embeddings',
  headers: {
    'Authorization': `Bearer ${openaiKey}`,
    'Content-Type': 'application/json'
  },
  body: {
    model: 'text-embedding-3-small',
    input: chunks.map(c => c.content.slice(0, 8000))
  },
  json: true
});

const withEmbeddings = chunks.map((c, i) => ({
  ...c,
  embedding: response.data[i].embedding
}));

return [{ json: { ...doc, chunks: withEmbeddings, _tokens: response.usage.total_tokens } }];

const doc = $('Extract & Chunk').first().json;
const withEmbeddings = $input.first().json;
const meta = JSON.parse($('AI Metadata Extraction').first().json.message.content);
const config = $('Set Source Config').first().json;

return [{
  json: {
    source: doc.source,
    guideline_code: doc.guideline_code,
    title: doc.title,
    url: doc.url,
    version: '1.0',
    effective_date: doc.pub_date.split('T')[0],
    source_hash: doc.source_hash,
    language: config.language,
    specialty: meta.specialty || [],
    conditions_covered: meta.conditions_covered || [],
    drugs_mentioned: meta.drugs_mentioned || [],
    patient_population: meta.patient_population || {},
    metadata: {
      icd10_codes: meta.icd10_codes,
      significance: meta.significance,
      rss_pub_date: doc.pub_date
    },
    chunks: withEmbeddings.chunks,
    ingested_by: `n8n:${doc.source.toLowerCase()}`
  }
}];
